importScripts("https://cdn.jsdelivr.net/pyodide/v0.25.0/full/pyodide.js");

function sendPatch(patch, buffers, msg_id) {
  self.postMessage({
    type: 'patch',
    patch: patch,
    buffers: buffers
  })
}

async function startApplication() {
  console.log("Loading pyodide!");
  self.postMessage({type: 'status', msg: 'Loading pyodide'})
  self.pyodide = await loadPyodide();
  self.pyodide.globals.set("sendPatch", sendPatch);
  console.log("Loaded!");
  await self.pyodide.loadPackage("micropip");
  const env_spec = ['https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/bokeh-3.4.3-py3-none-any.whl', 'https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/panel-1.4.5-py3-none-any.whl', 'pyodide-http==0.2.1', 'contextlib', 'html', 'io', 'math', 'pathlib', 'statistics']
  for (const pkg of env_spec) {
    let pkg_name;
    if (pkg.endsWith('.whl')) {
      pkg_name = pkg.split('/').slice(-1)[0].split('-')[0]
    } else {
      pkg_name = pkg
    }
    self.postMessage({type: 'status', msg: `Installing ${pkg_name}`})
    try {
      await self.pyodide.runPythonAsync(`
        import micropip
        await micropip.install('${pkg}');
      `);
    } catch(e) {
      console.log(e)
      self.postMessage({
	type: 'status',
	msg: `Error while installing ${pkg_name}`
      });
    }
  }
  console.log("Packages loaded!");
  self.postMessage({type: 'status', msg: 'Executing code'})
  const code = `
  \nimport asyncio\n\nfrom panel.io.pyodide import init_doc, write_doc\n\ninit_doc()\n\n# === FICHIER GENERE \u2014 ne pas editer (voir exercices.py et app.py) ===\n# -*- coding: utf-8 -*-\n"""Banque d'exercices Python \u2014 Initiation au metier d'analyste de fonds d'investissement (B3-AFE n\xb014).\n\nTgMaster University (prononcer "Tiji Master University").\n\nChaque exercice est un dictionnaire :\n  id        : identifiant court unique\n  seance    : numero de seance source (alignement avec les .md et les TPs Excel)\n  titre     : libelle affiche dans le menu deroulant\n  consigne  : enonce en Markdown (donnees + travail demande)\n  starter   : code de depart pre-rempli dans l'editeur (avec les donnees deja saisies)\n  solution  : solution de reference. Le moteur l'execute UNE fois au demarrage pour\n              en deduire les valeurs attendues des variables verifiees. On ne code donc\n              jamais "en dur" un resultat : la verite vient du calcul lui-meme.\n  verifs    : liste de controles (variable a produire, tolerance absolue, unite).\n\nLes donnees numeriques reprennent le contexte ecosysteme UEMOA / BRVM des 4 TPs Excel :\n  TP1 OPCVM (valeur liquidative, frais d'entree, parts)\n  TP2 performance et ratios de risque (Sharpe, Treynor, alpha de Jensen, ratio d'information)\n  TP3 Private Equity (MOIC, TVPI, DPI, RVPI, IRR, courbe en J)\n  TP4 valorisation d'une cible (DCF Gordon, multiples EV/EBITDA et PER, LBO MOIC/TRI)\nSociete de gestion fictive : SGO Asset Management (agreee AMF-UMOA, place d'Abidjan).\n"""\n\nEXERCICES = [\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s02_vl_opcvm",\n        "seance": 2,\n        "titre": "S2 \xb7 OPCVM \u2014 valeur liquidative et souscription",\n        "consigne": """\n### Valeur liquidative d'un OPCVM et frais d'entree\n\nLa SGO Asset Management (societe de gestion agreee AMF-UMOA, Abidjan) gere l'OPCVM\n**IVOIRE Actions BRVM**. Un client souscrit.\n\n| Parametre | Valeur |\n|-----------|--------|\n| Actif brut du fonds | 5 200 000 000 FCFA |\n| Dettes et frais a payer | 200 000 000 FCFA |\n| Nombre de parts en circulation | 500 000 |\n| Montant investi par le client (brut) | 10 000 000 FCFA |\n| Taux de frais d'entree | 3 % |\n\n**Travail demande :**\n1. Calculer l'**actif net** puis la **valeur liquidative** d'une part \u2192 \`actif_net\`, \`vl\`\n2. Calculer les **frais d'entree**, le **montant net investi** et le **nombre de parts achetees**\n   \u2192 \`frais\`, \`net_investi\`, \`parts_achetees\`\n\nRappels : VL = Actif net / Nombre de parts ; Parts achetees = Montant net investi / VL\n""",\n        "starter": """# Donnees\nactif_brut = 5_200_000_000\ndettes = 200_000_000\nnb_parts = 500_000\ninvesti = 10_000_000\ntaux_entree = 0.03\n\n# 1) Actif net et valeur liquidative\nactif_net = ...\nvl = ...\n\n# 2) Frais d'entree, montant net investi et nombre de parts achetees\nfrais = ...\nnet_investi = ...\nparts_achetees = ...\n\nprint("actif_net =", actif_net)\nprint("vl        =", vl, "FCFA")\nprint("parts     =", parts_achetees)\n""",\n        "solution": """\nactif_brut = 5_200_000_000\ndettes = 200_000_000\nnb_parts = 500_000\ninvesti = 10_000_000\ntaux_entree = 0.03\nactif_net = actif_brut - dettes\nvl = actif_net / nb_parts\nfrais = investi * taux_entree\nnet_investi = investi - frais\nparts_achetees = net_investi / vl\n""",\n        "verifs": [\n            {"var": "actif_net", "tol": 1000, "unite": "FCFA"},\n            {"var": "vl", "tol": 1.0, "unite": "FCFA"},\n            {"var": "parts_achetees", "tol": 0.5, "unite": "parts"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s03_performance_nette",\n        "seance": 3,\n        "titre": "S3 \xb7 Performance nette de frais et effet du TER",\n        "consigne": """\n### Performance brute, performance nette et cumul des frais\n\nLe fonds IVOIRE Actions BRVM affiche une performance brute, mais l'investisseur supporte\ndes frais de gestion annuels (TER, *Total Expense Ratio*).\n\n| Parametre | Valeur |\n|-----------|--------|\n| Performance brute du fonds (1 an) | 12 % |\n| Frais de gestion annuels (TER) | 2 % |\n| Horizon de placement | 5 ans |\n\n**Travail demande :**\n1. Calculer la **performance nette** de frais sur 1 an \u2192 \`perf_nette\`\n2. Calculer le **cumul** de performance nette sur 5 ans \u2192 \`cumul_net\`\n\nRappels : Perf nette = Perf brute - TER ; Cumul = (1 + perf nette)^horizon - 1\n""",\n        "starter": """perf_brute = 0.12\nter = 0.02\nhorizon = 5\n\n# 1) Performance nette de frais (1 an)\nperf_nette = ...\n\n# 2) Cumul de performance nette sur l'horizon\ncumul_net = ...\n\nprint("perf nette =", round(perf_nette * 100, 2), "%")\nprint("cumul net  =", round(cumul_net * 100, 2), "%")\n""",\n        "solution": """\nperf_brute = 0.12\nter = 0.02\nhorizon = 5\nperf_nette = perf_brute - ter\ncumul_net = (1 + perf_nette) ** horizon - 1\n""",\n        "verifs": [\n            {"var": "perf_nette", "tol": 0.0005, "unite": ""},\n            {"var": "cumul_net", "tol": 0.0005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s04_sharpe_treynor",\n        "seance": 4,\n        "titre": "S4 \xb7 Ratios de Sharpe et de Treynor",\n        "consigne": """\n### Performance ajustee du risque : Sharpe et Treynor\n\nUn analyste juge si le rendement d'un fonds est bon **compte tenu du risque pris**.\n\n| Parametre | Valeur |\n|-----------|--------|\n| Rendement annuel du fonds, Rp | 14 % |\n| Volatilite (ecart-type), \u03c3p | 16 % |\n| Beta du fonds vs BRVM | 1,10 |\n| Taux sans risque UEMOA, Rf | 4 % |\n\n**Travail demande :**\n1. Calculer la **prime de risque** du fonds \u2192 \`prime\`\n2. Calculer le **ratio de Sharpe** (risque total) \u2192 \`sharpe\`\n3. Calculer le **ratio de Treynor** (risque systematique) \u2192 \`treynor\`\n\nRappels : Sharpe = (Rp - Rf) / \u03c3p ; Treynor = (Rp - Rf) / beta\n""",\n        "starter": """rp = 0.14\nsigma = 0.16\nbeta = 1.10\nrf = 0.04\n\n# 1) Prime de risque du fonds\nprime = ...\n\n# 2) Ratio de Sharpe (par unite de risque total)\nsharpe = ...\n\n# 3) Ratio de Treynor (par unite de risque systematique)\ntreynor = ...\n\nprint("prime   =", round(prime * 100, 2), "%")\nprint("Sharpe  =", round(sharpe, 3))\nprint("Treynor =", round(treynor * 100, 2), "%")\n""",\n        "solution": """\nrp = 0.14\nsigma = 0.16\nbeta = 1.10\nrf = 0.04\nprime = rp - rf\nsharpe = (rp - rf) / sigma\ntreynor = (rp - rf) / beta\n""",\n        "verifs": [\n            {"var": "prime", "tol": 0.0005, "unite": ""},\n            {"var": "sharpe", "tol": 0.001, "unite": ""},\n            {"var": "treynor", "tol": 0.0005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s05_alpha_jensen",\n        "seance": 5,\n        "titre": "S5 \xb7 Alpha de Jensen et ratio d'information",\n        "consigne": """\n### Le gerant cree-t-il de la valeur ? Alpha de Jensen et ratio d'information\n\nOn compare le fonds a ce que le MEDAF (CAPM) justifierait, et a son indice de reference.\n\n| Parametre | Valeur |\n|-----------|--------|\n| Rendement du fonds, Rp | 14 % |\n| Taux sans risque, Rf | 4 % |\n| Beta du fonds | 1,10 |\n| Rendement du benchmark, Rm | 11 % |\n| Tracking error | 5 % |\n\n**Travail demande :**\n1. Calculer le **rendement attendu par le MEDAF** \u2192 \`rendement_medaf\`\n2. En deduire l'**alpha de Jensen** \u2192 \`alpha\`  (positif = valeur ajoutee)\n3. Calculer le **ratio d'information** \u2192 \`ir\`\n\nRappels : MEDAF = Rf + beta \xd7 (Rm - Rf) ; Alpha = Rp - MEDAF ; IR = (Rp - Rm) / Tracking error\n""",\n        "starter": """rp = 0.14\nrf = 0.04\nbeta = 1.10\nrm = 0.11\nte = 0.05\n\n# 1) Rendement attendu par le MEDAF\nrendement_medaf = ...\n\n# 2) Alpha de Jensen\nalpha = ...\n\n# 3) Ratio d'information\nir = ...\n\nprint("MEDAF attendu =", round(rendement_medaf * 100, 2), "%")\nprint("alpha         =", round(alpha * 100, 2), "%")\nprint("ratio info    =", round(ir, 3))\n""",\n        "solution": """\nrp = 0.14\nrf = 0.04\nbeta = 1.10\nrm = 0.11\nte = 0.05\nrendement_medaf = rf + beta * (rm - rf)\nalpha = rp - rendement_medaf\nir = (rp - rm) / te\n""",\n        "verifs": [\n            {"var": "rendement_medaf", "tol": 0.0005, "unite": ""},\n            {"var": "alpha", "tol": 0.0005, "unite": ""},\n            {"var": "ir", "tol": 0.001, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s06_multiples_pe",\n        "seance": 6,\n        "titre": "S6 \xb7 Private Equity \u2014 MOIC, DPI et RVPI",\n        "consigne": """\n### Multiples d'un fonds de capital-investissement\n\nLe fonds **AFRICA Growth FCPR** (panafricain, base a Abidjan) rend compte a ses souscripteurs.\n\n| Element | Valeur |\n|---------|--------|\n| Capital total appele (investi) | 1 000 000 000 FCFA |\n| Distributions cumulees (cash rendu) | 1 800 000 000 FCFA |\n| Valeur residuelle (NAV en portefeuille) | 700 000 000 FCFA |\n\n**Travail demande :**\n1. Calculer le **MOIC (= TVPI)** \u2192 \`moic\`\n2. Decomposer en **DPI** (deja distribue) et **RVPI** (encore en portefeuille) \u2192 \`dpi\`, \`rvpi\`\n\nRappels : MOIC = (Distributions + Valeur residuelle) / Capital appele ; DPI = Distributions / Capital ;\nRVPI = Valeur residuelle / Capital. Controle : MOIC = DPI + RVPI.\n""",\n        "starter": """appele = 1_000_000_000\ndistributions = 1_800_000_000\nnav = 700_000_000\n\n# 1) MOIC (= TVPI)\nmoic = ...\n\n# 2) DPI et RVPI\ndpi = ...\nrvpi = ...\n\nprint("MOIC =", round(moic, 2), "x")\nprint("DPI  =", round(dpi, 2), "x")\nprint("RVPI =", round(rvpi, 2), "x")\n""",\n        "solution": """\nappele = 1_000_000_000\ndistributions = 1_800_000_000\nnav = 700_000_000\nmoic = (distributions + nav) / appele\ndpi = distributions / appele\nrvpi = nav / appele\n""",\n        "verifs": [\n            {"var": "moic", "tol": 0.01, "unite": "x"},\n            {"var": "dpi", "tol": 0.01, "unite": "x"},\n            {"var": "rvpi", "tol": 0.01, "unite": "x"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s07_dcf_gordon",\n        "seance": 7,\n        "titre": "S7 \xb7 Valorisation par DCF (Gordon sur FCFF)",\n        "consigne": """\n### Valeur d'entreprise par actualisation des flux (modele de Gordon)\n\nLe fonds etudie le rachat d'**AGRO-CI SA** (agroalimentaire). On valorise la cible par un\nFCFF normatif qui croit a l'infini au taux g, actualise au WACC.\n\n| Parametre | Valeur |\n|-----------|--------|\n| FCFF annuel normatif | 600 000 000 FCFA |\n| Croissance perpetuelle des FCFF (g) | 2 % |\n| WACC | 10 % |\n| Dette financiere nette | 1 500 000 000 FCFA |\n\n**Travail demande :**\n1. Calculer la **valeur d'entreprise** par DCF \u2192 \`ev\`\n2. En deduire la **valeur des fonds propres** (equity) \u2192 \`equity\`\n\nRappels : EV = FCFF \xd7 (1 + g) / (WACC - g) ; Equity = EV - Dette nette\n""",\n        "starter": """fcff = 600_000_000\ng = 0.02\nwacc = 0.10\ndette_nette = 1_500_000_000\n\n# 1) Valeur d'entreprise par DCF (Gordon)\nev = ...\n\n# 2) Valeur des fonds propres\nequity = ...\n\nprint("EV     =", round(ev), "FCFA")\nprint("equity =", round(equity), "FCFA")\n""",\n        "solution": """\nfcff = 600_000_000\ng = 0.02\nwacc = 0.10\ndette_nette = 1_500_000_000\nev = fcff * (1 + g) / (wacc - g)\nequity = ev - dette_nette\n""",\n        "verifs": [\n            {"var": "ev", "tol": 1_000_000, "unite": "FCFA"},\n            {"var": "equity", "tol": 1_000_000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s08_multiples_ev_per",\n        "seance": 8,\n        "titre": "S8 \xb7 Valorisation par les multiples (EV/EBITDA, PER)",\n        "consigne": """\n### Recoupement par les multiples de marche\n\nOn recoupe la valorisation d'AGRO-CI SA par comparaison sectorielle (societes comparables).\n\n| Parametre | Valeur |\n|-----------|--------|\n| EBITDA annuel | 900 000 000 FCFA |\n| Multiple EV/EBITDA du secteur | 8 |\n| Resultat net annuel | 400 000 000 FCFA |\n| PER du secteur | 12 |\n| Dette financiere nette | 1 500 000 000 FCFA |\n\n**Travail demande :**\n1. Calculer l'**EV par le multiple EV/EBITDA** puis l'**equity** correspondant \u2192 \`ev_mult\`, \`equity_mult\`\n2. Calculer l'**equity par le PER** \u2192 \`equity_per\`\n\nRappels : EV = EV/EBITDA \xd7 EBITDA ; Equity (multiple) = EV - Dette nette ;\nEquity (PER) = PER \xd7 Resultat net\n""",\n        "starter": """ebitda = 900_000_000\nmult_ev_ebitda = 8\nresultat_net = 400_000_000\nper = 12\ndette_nette = 1_500_000_000\n\n# 1) EV par le multiple EV/EBITDA, puis equity\nev_mult = ...\nequity_mult = ...\n\n# 2) Equity par le PER\nequity_per = ...\n\nprint("EV (multiple)     =", round(ev_mult), "FCFA")\nprint("equity (multiple) =", round(equity_mult), "FCFA")\nprint("equity (PER)      =", round(equity_per), "FCFA")\n""",\n        "solution": """\nebitda = 900_000_000\nmult_ev_ebitda = 8\nresultat_net = 400_000_000\nper = 12\ndette_nette = 1_500_000_000\nev_mult = mult_ev_ebitda * ebitda\nequity_mult = ev_mult - dette_nette\nequity_per = per * resultat_net\n""",\n        "verifs": [\n            {"var": "ev_mult", "tol": 1_000_000, "unite": "FCFA"},\n            {"var": "equity_mult", "tol": 1_000_000, "unite": "FCFA"},\n            {"var": "equity_per", "tol": 1_000_000, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s09_lbo_moic_tri",\n        "seance": 9,\n        "titre": "S9 \xb7 Rendement d'un LBO \u2014 MOIC et TRI",\n        "consigne": """\n### Rendement d'un montage LBO (Leveraged Buy-Out)\n\nLe fonds rachete AGRO-CI SA avec un apport en fonds propres et de la dette, puis revend les\ntitres apres 5 ans.\n\n| Parametre | Valeur |\n|-----------|--------|\n| Apport en fonds propres (entree) | 2 500 000 000 FCFA |\n| Valeur des fonds propres a la revente | 5 750 000 000 FCFA |\n| Duree de detention | 5 ans |\n\n**Travail demande :**\n1. Calculer le **MOIC** de l'operation \u2192 \`moic\`\n2. Calculer le **TRI** annualise du fonds \u2192 \`tri\`\n\nRappels : MOIC = Valeur de revente / Apport ; TRI = MOIC^(1/duree) - 1\n""",\n        "starter": """apport = 2_500_000_000\nrevente = 5_750_000_000\nduree = 5\n\n# 1) MOIC du LBO\nmoic = ...\n\n# 2) TRI annualise\ntri = ...\n\nprint("MOIC =", round(moic, 2), "x")\nprint("TRI  =", round(tri * 100, 2), "%")\n""",\n        "solution": """\napport = 2_500_000_000\nrevente = 5_750_000_000\nduree = 5\nmoic = revente / apport\ntri = moic ** (1 / duree) - 1\n""",\n        "verifs": [\n            {"var": "moic", "tol": 0.01, "unite": "x"},\n            {"var": "tri", "tol": 0.001, "unite": ""},\n        ],\n    },\n\n    # ================================================================== #\n    #  TIER AVANCE \u2014 exercices multi-etapes (fonctions, boucles,         #\n    #  iteration, decision). Niveau MBA / \u2605\u2605\u2605.                          #\n    # ================================================================== #\n    {\n        "id": "adv_irr_pe_dichotomie",\n        "seance": 6,\n        "niveau": "avance",\n        "titre": "A1 \xb7 Private Equity \u2014 IRR par dichotomie",\n        "consigne": """\n### Taux de rendement interne (IRR) d'un fonds par recherche iterative\n\nLe fonds AFRICA Growth FCPR appelle puis distribue des capitaux. Echeancier des **flux nets\npour le souscripteur** (en millions FCFA), de l'annee 0 a l'annee 5 :\n\n| Annee | 0 | 1 | 2 | 3 | 4 | 5 |\n|-------|----|----|----|----|----|----|\n| Flux | -600 | -400 | +200 | +500 | +600 | +1 200 |\n\nL'**IRR** est le taux \`r\` qui annule la valeur actuelle nette (VAN) de l'echeancier. Il\nn'existe pas de formule directe : on le **cherche par dichotomie**.\n\n**Travail demande :**\n1. Completer la fonction \`van(r)\` (somme des flux actualises ; l'annee 0 n'est pas actualisee).\n2. Completer la dichotomie : la VAN **decroit** quand le taux monte, donc si \`van(milieu) > 0\`\n   le taux est trop bas \u2192 il faut remonter \`bas\`.\n3. Recuperer le taux trouve dans \`irr\`.\n""",\n        "starter": """flux = [-600, -400, 200, 500, 600, 1200]   # millions FCFA, annees 0..5\n\ndef van(r):\n    # Somme des flux actualises (enumerate commence a t=0 : l'annee 0 n'est pas actualisee)\n    return sum(f / (1 + r) ** t for t, f in enumerate(flux))\n\nbas, haut = 0.0001, 1.0\nfor _ in range(200):\n    milieu = (bas + haut) / 2\n    v = van(milieu)\n    if abs(v) < 0.001:\n        break\n    if v > 0:        # VAN positive -> taux trop bas -> remonter 'bas'\n        bas = ...\n    else:            # VAN negative -> taux trop haut -> descendre 'haut'\n        haut = ...\n\nirr = milieu\n\nprint("IRR =", round(irr * 100, 2), "%")\nprint("VAN au taux trouve =", round(van(irr), 4))\n""",\n        "solution": """\nflux = [-600, -400, 200, 500, 600, 1200]\n\ndef van(r):\n    return sum(f / (1 + r) ** t for t, f in enumerate(flux))\n\nbas, haut = 0.0001, 1.0\nfor _ in range(200):\n    milieu = (bas + haut) / 2\n    v = van(milieu)\n    if abs(v) < 0.001:\n        break\n    if v > 0:\n        bas = milieu\n    else:\n        haut = milieu\nirr = milieu\n""",\n        "verifs": [\n            {"var": "irr", "tol": 0.001, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_courbe_j",\n        "seance": 6,\n        "niveau": "avance",\n        "titre": "A2 \xb7 Private Equity \u2014 courbe en J (cumul des flux)",\n        "consigne": """\n### La courbe en J : suivre le cumul des flux annee par annee\n\nOn reprend l'echeancier du fonds (millions FCFA) : \`[-600, -400, 200, 500, 600, 1200]\`.\nLa **courbe en J** trace le cumul des flux nets : il plonge en negatif (phase\nd'investissement) puis remonte avec les distributions.\n\n**Travail demande :** parcourir les flux en cumulant, et determiner :\n1. le **cumul final** apres l'annee 5 \u2192 \`cumul_final\`\n2. la **premiere annee ou le cumul redevient positif** \u2192 \`annee_retour\`\n3. le **point le plus bas** du cumul (le creux du J) \u2192 \`cumul_min\`\n\nAstuce : initialise \`cumul_min\` a une grande valeur et garde le minimum rencontre.\n""",\n        "starter": """flux = [-600, -400, 200, 500, 600, 1200]   # annees 0..5\n\ncumul = 0.0\ncumul_min = 999999\nannee_retour = None\nfor annee, f in enumerate(flux):\n    cumul = cumul + f\n    if cumul < cumul_min:\n        cumul_min = ...\n    if annee_retour is None and cumul > 0:\n        annee_retour = ...\n\ncumul_final = cumul\n\nprint("cumul final  =", cumul_final)\nprint("annee retour =", annee_retour)\nprint("creux du J   =", cumul_min)\n""",\n        "solution": """\nflux = [-600, -400, 200, 500, 600, 1200]\ncumul = 0.0\ncumul_min = 999999\nannee_retour = None\nfor annee, f in enumerate(flux):\n    cumul = cumul + f\n    if cumul < cumul_min:\n        cumul_min = cumul\n    if annee_retour is None and cumul > 0:\n        annee_retour = annee\ncumul_final = cumul\n""",\n        "verifs": [\n            {"var": "cumul_final", "tol": 0.5, "unite": "M FCFA"},\n            {"var": "annee_retour", "tol": 0.5, "unite": ""},\n            {"var": "cumul_min", "tol": 0.5, "unite": "M FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_screening_fonds",\n        "seance": 4,\n        "niveau": "avance",\n        "titre": "A3 \xb7 Selection de fonds par le ratio de Sharpe",\n        "consigne": """\n### Comparer plusieurs fonds : le meilleur Sharpe\n\nUn analyste compare 4 fonds disponibles sur la place. Taux sans risque UEMOA \`Rf = 4 %\`.\n\n| Fonds | Rendement Rp | Volatilite \u03c3 |\n|-------|--------------|--------------|\n| A | 14 % | 16 % |\n| B | 10 % | 8 % |\n| C | 18 % | 25 % |\n| D | 9 % | 10 % |\n\n**Travail demande :** parcourir la liste, calculer le ratio de Sharpe de chaque fonds, puis :\n1. retenir le **meilleur ratio de Sharpe** \u2192 \`sharpe_max\`\n2. compter combien de fonds ont un Sharpe **strictement superieur a 0,5** \u2192 \`nb_bons\`\n\nRappel : Sharpe = (Rp - Rf) / \u03c3.\n""",\n        "starter": """rf = 0.04\nfonds = [\n    {"nom": "A", "rp": 0.14, "sigma": 0.16},\n    {"nom": "B", "rp": 0.10, "sigma": 0.08},\n    {"nom": "C", "rp": 0.18, "sigma": 0.25},\n    {"nom": "D", "rp": 0.09, "sigma": 0.10},\n]\n\nsharpe_max = -999.0\nnb_bons = 0\nfor f in fonds:\n    sharpe = ...                 # (Rp - Rf) / sigma\n    if sharpe > sharpe_max:\n        sharpe_max = ...\n    if sharpe > 0.5:\n        nb_bons = nb_bons + 1\n\nprint("meilleur Sharpe =", round(sharpe_max, 3))\nprint("fonds Sharpe>0,5 =", nb_bons)\n""",\n        "solution": """\nrf = 0.04\nfonds = [\n    {"nom": "A", "rp": 0.14, "sigma": 0.16},\n    {"nom": "B", "rp": 0.10, "sigma": 0.08},\n    {"nom": "C", "rp": 0.18, "sigma": 0.25},\n    {"nom": "D", "rp": 0.09, "sigma": 0.10},\n]\nsharpe_max = -999.0\nnb_bons = 0\nfor f in fonds:\n    sharpe = (f["rp"] - rf) / f["sigma"]\n    if sharpe > sharpe_max:\n        sharpe_max = sharpe\n    if sharpe > 0.5:\n        nb_bons = nb_bons + 1\n""",\n        "verifs": [\n            {"var": "sharpe_max", "tol": 0.001, "unite": ""},\n            {"var": "nb_bons", "tol": 0.5, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_dcf_2etages",\n        "seance": 7,\n        "niveau": "avance",\n        "titre": "A4 \xb7 DCF a 2 etages (croissance explicite + Gordon)",\n        "consigne": """\n### Valorisation DCF en deux temps : flux explicites puis valeur terminale\n\nLe DCF de Gordon simple suppose une croissance constante a l'infini. Plus realiste : projeter\nexplicitement quelques annees, puis poser une valeur terminale.\n\n- **Phase explicite** : FCFF de l'annee 1 = **600** (M FCFA), croissance **+8 %/an pendant 3 ans**.\n- **Phase terminale** : ensuite, croissance perpetuelle **g = 2 %**. WACC = **10 %**.\n\n**Travail demande :**\n1. Dans la boucle, **cumuler la valeur actuelle** de chaque FCFF des annees 1 a 3 \u2192 \`va_explicite\`.\n2. Calculer la **valeur terminale** en fin d'annee 3 : \`VT = FCFF3 \xd7 (1 + g) / (WACC - g)\`.\n3. Actualiser VT sur 3 ans et l'ajouter \u2192 valeur d'entreprise \`ev\`.\n\nRappel : actualiser un flux de l'annee t = flux / (1 + WACC)^t.\n""",\n        "starter": """fcff = 600          # FCFF de l'annee 1 (M FCFA)\ng_court = 0.08      # croissance phase explicite\ng_long = 0.02       # croissance perpetuelle\nwacc = 0.10\nannees = 3\n\n# 1) Phase explicite : cumuler la VA de chaque FCFF\nva_explicite = 0.0\nflux = fcff\nfor t in range(1, annees + 1):\n    va_explicite = va_explicite + ...      # VA du FCFF de l'annee t\n    if t < annees:\n        flux = flux * (1 + g_court)        # FCFF de l'annee suivante\n\nfcff3 = flux        # FCFF de la derniere annee explicite\n\n# 2) Valeur terminale en fin d'annee 3\nVT = ...\n\n# 3) EV = VA des flux explicites + VA de la valeur terminale\nev = va_explicite + ...\n\nprint("va_explicite =", round(va_explicite, 2))\nprint("VT           =", round(VT, 2))\nprint("ev           =", round(ev, 2), "M FCFA")\n""",\n        "solution": """\nfcff = 600\ng_court = 0.08\ng_long = 0.02\nwacc = 0.10\nannees = 3\nva_explicite = 0.0\nflux = fcff\nfor t in range(1, annees + 1):\n    va_explicite = va_explicite + flux / (1 + wacc) ** t\n    if t < annees:\n        flux = flux * (1 + g_court)\nfcff3 = flux\nVT = fcff3 * (1 + g_long) / (wacc - g_long)\nev = va_explicite + VT / (1 + wacc) ** annees\n""",\n        "verifs": [\n            {"var": "va_explicite", "tol": 1.0, "unite": "M FCFA"},\n            {"var": "VT", "tol": 1.0, "unite": "M FCFA"},\n            {"var": "ev", "tol": 2.0, "unite": "M FCFA"},\n        ],\n    },\n]\n\n\ndef exercice_par_id(eid):\n    for ex in EXERCICES:\n        if ex["id"] == eid:\n            return ex\n    return None\n\n\n# === app.py ===\n# -*- coding: utf-8 -*-\n"""App Panel \u2014 Exercices Python interactifs\nInitiation au metier d'analyste de fonds d'investissement (B3-AFE n\xb014)\nTgMaster University (prononcer "Tiji Master University").\n\nL'etudiant ecrit son code dans l'editeur, clique "Verifier", et l'app :\n  1. execute le code (sortie texte capturee),\n  2. compare la VALEUR des variables attendues a la solution de reference,\n     avec une tolerance numerique (robuste : pas de comparaison de chaines).\n\nLancement local :\n    pip install panel\n    panel serve app.py --show\n\nDeploiement (voir README.md) :\n    - Hugging Face Spaces (Docker) ou Railway  -> mode serveur\n    - panel convert app.py --to pyodide-worker  -> HTML statique (zero serveur),\n      a embarquer dans Moodle via une iframe.\n"""\nimport io\nimport contextlib\nimport math\nimport pathlib\nimport statistics\n\nimport panel as pn\n\n\n# --- Habillage "Indigo clair" (custom_panel.css place a cote de ce fichier) ---\n# CSS inline (compatible Pyodide, aucune lecture de fichier au runtime)\n_RAW_CSS = [r'''\n/* ===========================================================================\n   custom_panel.css \u2014 Habillage "Indigo clair" pour l'app Panel (app.py)\n   \xc0 placer \xe0 c\xf4t\xe9 de app.py. Charg\xe9 automatiquement par app.py (voir ce fichier).\n   Pour changer de direction visuelle : modifier les 6 variables de :root.\n   =========================================================================== */\n@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');\n\n:root {\n  --accent:        #3b46a0;\n  --accent-strong: #2b3576;\n  --accent-soft:   #eef0fb;\n  --page-bg:       #f1f3f9;\n  --surface:       #ffffff;\n  --surface-2:     #f7f8fc;\n  --border:        #e4e7f0;\n  --border-strong: #d2d7e4;\n  --text:          #1b2030;\n  --text-muted:    #687087;\n  --success:       #1b8a52;\n  --danger:        #c0492f;\n  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n  --font-mono: 'JetBrains Mono', ui-monospace, Menlo, Consolas, monospace;\n}\n\nbody, .bk-root {\n  font-family: var(--font-sans) !important;\n  color: var(--text);\n  background: var(--page-bg) !important;\n}\n.bk-root .bk-Column { background: transparent; }\n\n/* S\xe9lecteur d'exercice */\nselect.bk-input, .bk-input {\n  font-family: var(--font-sans) !important;\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 8px !important;\n  color: var(--text) !important;\n  background: var(--surface) !important;\n  font-weight: 600;\n  padding: 9px 12px !important;\n}\nselect.bk-input:focus, .bk-input:focus {\n  outline: none !important;\n  border-color: var(--accent) !important;\n  box-shadow: 0 0 0 3px rgba(59,70,160,0.16) !important;\n}\n.bk-input-group label, label.bk {\n  font-weight: 600 !important;\n  color: var(--text-muted) !important;\n  font-size: 12px !important;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n/* Boutons */\n.bk-btn {\n  font-family: var(--font-sans) !important;\n  font-weight: 600 !important;\n  border-radius: 8px !important;\n  padding: 9px 16px !important;\n  border: 1px solid transparent !important;\n  transition: background .15s ease, color .15s ease;\n}\n.bk-btn-primary { background: var(--accent) !important; border-color: var(--accent) !important; color: #fff !important; }\n.bk-btn-primary:hover { background: var(--accent-strong) !important; }\n.bk-btn-default { background: var(--surface) !important; color: var(--text-muted) !important; border-color: var(--border-strong) !important; }\n.bk-btn-default:hover { background: var(--surface-2) !important; color: var(--text) !important; }\n.bk-btn-warning { background: transparent !important; color: var(--accent-strong) !important; border-color: var(--border-strong) !important; }\n.bk-btn-warning:hover { background: var(--accent-soft) !important; }\n.bk-btn-warning.bk-active { background: var(--accent-soft) !important; border-color: var(--accent) !important; }\n\n/* \xc9diteur de code (Ace) */\n.bk-root .ace_editor {\n  border: 1px solid var(--border) !important;\n  border-radius: 12px !important;\n  font-family: var(--font-mono) !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,0.06);\n  overflow: hidden;\n}\n\n/* \xc9nonc\xe9 + feedback (panes Markdown) \u2014 plats, sans carte (les cartes sont g\xe9r\xe9es par .main-panel) */\n.bk-root .markdown { line-height: 1.55; }\n.bk-root .markdown h3 { color: var(--text); font-weight: 800; }\n.bk-root .markdown code {\n  font-family: var(--font-mono) !important;\n  background: var(--accent-soft);\n  color: var(--accent-strong);\n  padding: 1.5px 6px; border-radius: 5px; font-size: 0.86em;\n}\n.bk-root .markdown table {\n  border-collapse: separate; border-spacing: 0;\n  border: 1px solid var(--border); border-radius: 10px; overflow: hidden;\n}\n.bk-root .markdown th {\n  background: var(--surface-2); text-align: left;\n  padding: 9px 13px !important; border-bottom: 1px solid var(--border);\n}\n.bk-root .markdown td {\n  padding: 8px 13px !important; border-bottom: 1px solid var(--border);\n  font-variant-numeric: tabular-nums;\n}\n.bk-root .markdown tr:nth-child(even) td { background: var(--surface-2); }\n\n.bk-root hr { border: none; border-top: 1px solid var(--border); margin: 6px 0; }\n\n/* =========================================================================\n   LAYOUT MAQUETTE \u2014 header + progression / sidebar cartes / panneau + \xe9diteur\n   ========================================================================= */\n\n/* --- En-t\xeate gradient + barre de progression --- */\n.app-header {\n  background: linear-gradient(100deg, var(--accent-strong), var(--accent)) !important;\n  border-radius: 16px !important;\n  padding: 18px 26px !important;\n  box-shadow: 0 8px 24px rgba(20,26,50,.14);\n  align-items: center !important;\n}\n.hdr-sub {\n  color: rgba(255,255,255,.72); font-size: 11.5px; font-weight: 600;\n  letter-spacing: .06em; text-transform: uppercase;\n}\n.hdr-title {\n  color: #fff; font-size: 20px; font-weight: 800; letter-spacing: -.01em; margin-top: 3px;\n}\n.prog-wrap { text-align: right; min-width: 200px; }\n.prog-pill {\n  color: #fff; font-size: 13px; font-weight: 700; margin-bottom: 7px;\n}\n.prog-track {\n  width: 200px; height: 9px; border-radius: 99px;\n  background: rgba(255,255,255,.22); overflow: hidden; margin-left: auto;\n}\n.prog-fill {\n  height: 100%; border-radius: 99px; background: #fff;\n  transition: width .35s ease;\n}\n\n/* --- Sidebar \xab Parcours d'exercices \xbb --- */\n.sidebar {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 16px 14px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.sb-title { font-size: 14px; font-weight: 800; color: var(--text); }\n.sb-sub { font-size: 11.5px; color: var(--text-muted); margin-top: 1px; margin-bottom: 6px; }\n.section-head {\n  font-size: 10.5px; font-weight: 700; color: var(--text-muted);\n  letter-spacing: .07em; text-transform: uppercase;\n  margin: 14px 6px 6px;\n}\n\n/* Carte exercice = Row [badge | bouton-label | statut] */\n.exo-card {\n  align-items: center !important;\n  flex-wrap: nowrap !important;\n  overflow: hidden !important;\n  border: 1px solid var(--border) !important;\n  border-radius: 11px !important;\n  margin-bottom: 7px !important;\n  padding: 4px 8px !important;\n  background: var(--surface) !important;\n  transition: border-color .15s ease, background .15s ease, box-shadow .15s ease;\n}\n.exo-card:hover { border-color: var(--border-strong) !important; background: var(--surface-2) !important; }\n.exo-card.actif {\n  border-color: var(--accent) !important;\n  background: var(--accent-soft) !important;\n  box-shadow: 0 0 0 3px rgba(59,70,160,.12) !important;\n}\n/* TOUS les enfants flex doivent pouvoir r\xe9tr\xe9cir sous la largeur de leur contenu */\n.exo-card > * { min-width: 0 !important; }\n/* Badge (gauche) et pastille (droite) : taille fixe, ne r\xe9tr\xe9cissent pas */\n.exo-card > *:first-child { flex: 0 0 auto !important; }\n.exo-card > *:last-child  { flex: 0 0 auto !important; }\n/* Le bouton-label au milieu : prend l'espace restant et r\xe9tr\xe9cit */\n.exo-card > *:nth-child(2) { flex: 1 1 auto !important; min-width: 0 !important; }\n\n.exo-badge-sb {\n  font-family: var(--font-mono) !important; font-size: 11px; font-weight: 700;\n  color: var(--accent-strong); background: var(--accent-soft);\n  border: 1px solid var(--border); border-radius: 7px;\n  padding: 4px 7px; min-width: 34px; text-align: center;\n}\n.exo-card.actif .exo-badge-sb { background: #fff; }\n/* Le bouton-label occupe l'espace, transparent et sans bordure, texte tronqu\xe9 proprement */\n.exo-card .bk-btn, .exo-card .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  text-align: left !important; color: var(--text) !important;\n  font-weight: 600 !important; font-size: 12.5px !important;\n  padding: 6px 4px !important; line-height: 1.35 !important;\n  min-width: 0 !important; width: 100% !important; max-width: 100% !important;\n  display: block !important;\n  white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important;\n}\n.exo-card .bk-btn:hover { background: transparent !important; color: var(--accent-strong) !important; }\n.exo-stat {\n  flex: 0 0 auto; width: 20px; height: 20px; border-radius: 99px;\n  border: 2px solid var(--border-strong);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 12px; color: transparent;\n}\n.exo-card.ok .exo-stat {\n  border-color: var(--success); background: var(--success); color: #fff;\n}\n\n/* --- Panneau principal --- */\n.main-panel {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 22px 26px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.exo-head { align-items: center !important; }\n.exo-badge {\n  font-family: var(--font-mono) !important; font-weight: 800; font-size: 14px;\n  color: #fff; background: var(--accent); border-radius: 9px;\n  padding: 7px 11px; margin-right: 4px;\n}\n.exo-h-title { font-size: 18px; font-weight: 800; color: var(--text); }\n.tag-base, .tag-avance {\n  font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;\n  padding: 4px 9px; border-radius: 99px;\n}\n.tag-base { color: var(--accent-strong); background: var(--accent-soft); }\n.tag-avance { color: #fff; background: linear-gradient(100deg, var(--accent-strong), var(--accent)); }\n\n/* --- Fen\xeatre \xe9diteur style macOS --- */\n.editor-window {\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 12px !important; overflow: hidden;\n  box-shadow: 0 6px 18px rgba(20,26,50,.10);\n  background: #fbfbfd;\n}\n.editor-titlebar {\n  display: flex; align-items: center; gap: 9px;\n  background: var(--surface-2); border-bottom: 1px solid var(--border);\n  padding: 8px 13px;\n}\n.editor-titlebar .dot { width: 12px; height: 12px; border-radius: 99px; display: inline-block; }\n.dot-r { background: #ec6a5e; } .dot-y { background: #f4be4f; } .dot-g { background: #61c554; }\n.editor-titlebar .fname {\n  font-family: var(--font-mono) !important; font-size: 12px; color: var(--text-muted);\n  margin-left: 6px;\n}\n.editor-window .ace_editor { border: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n/* --- Carte feedback --- */\n.feedback-card {\n  background: var(--surface-2); border: 1px solid var(--border);\n  border-radius: 12px; padding: 6px 18px !important; margin-top: 4px !important;\n}\n\n/* --- Corps deux colonnes responsive --- */\n.body-row { align-items: flex-start !important; flex-wrap: wrap !important; gap: 16px; }\n.body-row > div { min-width: 0 !important; }\n.sidebar { flex: 0 0 280px !important; }\n.main-panel { flex: 1 1 420px !important; min-width: 0 !important; }\n/* Sur \xe9cran \xe9troit : la sidebar passe pleine largeur au-dessus du panneau */\n@media (max-width: 820px) {\n  .sidebar { flex-basis: 100% !important; }\n}\n\n''']\n\npn.extension("codeeditor", sizing_mode="stretch_width", raw_css=_RAW_CSS)\n\n# Palette de la maquette (Indigo clair)\nNAVY = "#2b3576"   # accent indigo (titres, messages neutres)\nRED = "#c0492f"    # erreurs\nGREEN = "#1b8a52"  # succes\n\n# Environnement d'execution autorise : modules surs pour du calcul financier.\nSAFE_MODULES = {"math": math, "statistics": statistics}\n\n\n# --------------------------------------------------------------------------- #\n# Moteur d'execution et de verification\n# --------------------------------------------------------------------------- #\ndef executer_code(code):\n    """Execute \`code\` dans un espace de noms neuf.\n    Retourne (namespace, sortie_texte, erreur_ou_None).\n    Pas de subprocess -> compatible Pyodide (WASM, execution dans le navigateur).\n    """\n    ns = dict(SAFE_MODULES)\n    sortie = io.StringIO()\n    erreur = None\n    try:\n        with contextlib.redirect_stdout(sortie):\n            exec(code, ns)  # noqa: S102 - outil pedagogique, execution voulue\n    except Exception as exc:  # noqa: BLE001\n        erreur = f"{type(exc).__name__} : {exc}"\n    return ns, sortie.getvalue(), erreur\n\n\n# Valeurs de reference : calculees UNE fois depuis la solution de chaque exercice.\ndef _valeurs_attendues(ex):\n    ns, _, err = executer_code(ex["solution"])\n    if err:\n        raise RuntimeError(f"Solution invalide pour {ex['id']} : {err}")\n    return {v["var"]: ns[v["var"]] for v in ex["verifs"]}\n\n\nATTENDU = {ex["id"]: _valeurs_attendues(ex) for ex in EXERCICES}\n\n\ndef verifier(ex, code):\n    """Renvoie (ok_global, markdown_feedback)."""\n    # Garde-fou pedagogique : tant qu'il reste des "..." (placeholders a completer),\n    # on ne lance pas le code -> on evite un TypeError cryptique sur Ellipsis.\n    lignes_a_completer = [i for i, ligne in enumerate(code.splitlines(), start=1)\n                          if "..." in ligne]\n    if lignes_a_completer:\n        nums = ", ".join(str(n) for n in lignes_a_completer)\n        return False, (f"<span style='color:{NAVY}'>\u270f\ufe0f Il reste des \`...\` \xe0 "\n                       f"compl\xe9ter (ligne(s) {nums}). Remplace chaque \`...\` par "\n                       f"ta formule, puis clique de nouveau sur "\n                       f"<b>V\xe9rifier</b>.</span>")\n\n    ns, sortie, erreur = executer_code(code)\n\n    lignes = []\n    if sortie.strip():\n        lignes.append("**Sortie de ton code :**")\n        lignes.append("\`\`\`\\n" + sortie.rstrip() + "\\n\`\`\`")\n\n    if erreur:\n        lignes.append(f"<span style='color:{RED}'>\u274c **Erreur d'ex\xe9cution :** "\n                      f"{erreur}</span>")\n        return False, "\\n\\n".join(lignes)\n\n    attendu = ATTENDU[ex["id"]]\n    tous_ok = True\n    details = []\n    for v in ex["verifs"]:\n        nom = v["var"]\n        unite = (" " + v["unite"]) if v["unite"] else ""\n        if nom not in ns or ns[nom] is Ellipsis:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` n'est pas "\n                           f"encore calcul\xe9 (il vaut \`...\`).</span>")\n            continue\n        try:\n            val = float(ns[nom])\n        except (TypeError, ValueError):\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` doit \xeatre un "\n                           f"nombre.</span>")\n            continue\n        ref = float(attendu[nom])\n        if abs(val - ref) <= v["tol"]:\n            details.append(f"<span style='color:{GREEN}'>\u2705 \`{nom}\` = "\n                           f"{_fmt(val)}{unite}</span>")\n        else:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` = {_fmt(val)}"\n                           f"{unite} \u2014 ce n'est pas la valeur attendue.</span>")\n\n    lignes.append("\\n".join(details))\n    if tous_ok:\n        lignes.append(f"<h3 style='color:{GREEN}'>\U0001f389 Exercice r\xe9ussi \u2014 "\n                      f"bravo !</h3>")\n    else:\n        lignes.append(f"<span style='color:{NAVY}'>V\xe9rifie tes formules et "\n                      f"r\xe9essaie.</span>")\n    return tous_ok, "\\n\\n".join(lignes)\n\n\ndef _fmt(x):\n    """Affichage lisible : entier si rond, sinon 4 decimales max."""\n    if abs(x - round(x)) < 1e-9:\n        return f"{int(round(x))}"\n    return f"{x:.4f}".rstrip("0").rstrip(".")\n\n\n# --------------------------------------------------------------------------- #\n# Interface \u2014 maquette : en-tete + progression / sidebar cartes / panneau editeur\n# --------------------------------------------------------------------------- #\nimport html as _html\n\nTOTAL = len(EXERCICES)\nsolved = set()                       # ids des exercices reussis\netat = {"id": EXERCICES[0]["id"]}     # exercice courant\n\n\ndef _split_titre(titre):\n    """'A1 \xb7 Obligation \u2014 trouver le YTM' -> ('A1', 'Obligation \u2014 trouver le YTM').\n    'Exercice 1 \xb7 ...' garde le badge tel quel ; sinon numerote."""\n    if "\xb7" in titre:\n        badge, label = titre.split("\xb7", 1)\n        return badge.strip(), label.strip()\n    return "", titre.strip()\n\n\n# --- Widgets de contenu ----------------------------------------------------- #\nconsigne = pn.pane.Markdown(sizing_mode="stretch_width")\nediteur = pn.widgets.CodeEditor(language="python", theme="tomorrow",\n                                height=360, sizing_mode="stretch_width")\nbouton = pn.widgets.Button(name="\u25b6 V\xe9rifier", button_type="primary", width=150)\nbouton_reset = pn.widgets.Button(name="\u21ba R\xe9initialiser", button_type="default",\n                                 width=150)\nbouton_sol = pn.widgets.Toggle(name="\U0001f441 Voir la solution", button_type="warning",\n                               width=160)\nfeedback = pn.pane.Markdown(sizing_mode="stretch_width")\n\nexo_head = pn.pane.HTML(sizing_mode="stretch_width")\ntitlebar = pn.pane.HTML(sizing_mode="stretch_width")\nprogress = pn.pane.HTML()\n\n\ndef _titlebar_html(eid):\n    n = next((i for i, e in enumerate(EXERCICES, 1) if e["id"] == eid), 1)\n    return ("<div class='editor-titlebar'>"\n            "<span class='dot dot-r'></span><span class='dot dot-y'></span>"\n            "<span class='dot dot-g'></span>"\n            f"<span class='fname'>exercice_{n:02d}.py</span></div>")\n\n\ndef _exo_head_html(ex):\n    badge, label = _split_titre(ex["titre"])\n    avance = ex.get("niveau") == "avance"\n    tag = ("<span class='tag-avance'>Avanc\xe9 \u2605\u2605\u2605</span>" if avance\n           else "<span class='tag-base'>Base \u2605</span>")\n    badge_html = (f"<span class='exo-badge'>{_html.escape(badge)}</span>"\n                  if badge else "")\n    return ("<div class='exo-head' style='display:flex;align-items:center;gap:12px'>"\n            f"{badge_html}"\n            f"<span class='exo-h-title'>{_html.escape(label)}</span>"\n            f"<span style='flex:1 1 auto'></span>{tag}</div>")\n\n\ndef maj_progress():\n    pct = round(100 * len(solved) / TOTAL)\n    progress.object = (\n        "<div class='prog-wrap'>"\n        f"<div class='prog-pill'>{len(solved)} / {TOTAL} r\xe9ussis</div>"\n        f"<div class='prog-track'><div class='prog-fill' style='width:{pct}%'></div></div>"\n        "</div>")\n\n\n# --- Cartes de la sidebar --------------------------------------------------- #\n# Une carte = Row[badge | bouton-label | pastille statut], css togglee a l'execution.\n# Bokeh 3.x rend chaque widget dans son propre shadow root : le CSS global\n# (.exo-card .bk-btn) ne traverse PAS ces frontieres. On injecte donc le style\n# directement dans le shadow root de chaque composant via stylesheets=[...].\ncartes = {}     # eid -> pn.Row\n_boutons_sb = {}\n_stats_sb = {}  # eid -> pn.pane.HTML (pastille statut)\n\n# Pastilles statut : styles INLINE (le selecteur .exo-card.ok .exo-stat ne traverse\n# pas le shadow root du pane HTML \u2014 on change donc directement le contenu du pane).\n_STAT_BASE = ("width:20px;height:20px;border-radius:99px;"\n              "border:2px solid #d2d7e4;display:flex;align-items:center;"\n              "justify-content:center;font-size:12px;color:transparent")\n_STAT_OK = ("width:20px;height:20px;border-radius:99px;"\n            "border:2px solid #1b8a52;background:#1b8a52;color:#fff;"\n            "display:flex;align-items:center;justify-content:center;font-size:12px")\n_STAT_VIDE = f"<div style='{_STAT_BASE}'>\u2713</div>"\n_STAT_PLEIN = f"<div style='{_STAT_OK}'>\u2713</div>"\n\n# Style injecte dans le shadow root de la Row (carte) : fixe les flex des enfants.\nROW_SHEET = """\n:host { align-items: center; }\n.bk-panel-models-markup-HTML { flex: 0 0 auto !important; }\n.bk-panel-models-widgets-Button { flex: 1 1 auto !important; min-width: 0 !important; }\n"""\n\n# Style injecte dans le shadow root du Button-label : transparent, titre sur 2 lignes (lisible).\nBTN_SHEET = """\n:host { width: 100%; min-width: 0; }\n.bk-btn, .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  color: #1b2030 !important; text-align: left !important;\n  font-weight: 600 !important; font-size: 12.5px !important;\n  padding: 6px 4px !important; line-height: 1.3 !important;\n  display: block !important; width: 100% !important; max-width: 100% !important;\n  min-width: 0 !important;\n  white-space: normal !important; overflow-wrap: break-word !important; word-break: normal !important;\n}\n.bk-btn:hover, .bk-btn-default:hover { background: transparent !important; color: #2b3576 !important; }\n"""\n\n\ndef _make_carte(ex):\n    badge, label = _split_titre(ex["titre"])\n    b = pn.widgets.Button(name=label, button_type="default", sizing_mode="stretch_width",\n                          stylesheets=[BTN_SHEET])\n    b.on_click(lambda evt, eid=ex["id"]: select(eid))\n    _boutons_sb[ex["id"]] = b\n    stat = pn.pane.HTML(_STAT_VIDE, width=26)\n    _stats_sb[ex["id"]] = stat\n    badge_pane = pn.pane.HTML(f"<div class='exo-badge-sb'>{_html.escape(badge or '\u2022')}</div>",\n                              width=46)\n    row = pn.Row(badge_pane, b, stat, css_classes=["exo-card"],\n                 stylesheets=[ROW_SHEET], sizing_mode="stretch_width")\n    cartes[ex["id"]] = row\n    return row\n\n\ndef _maj_cartes():\n    for eid, row in cartes.items():\n        cls = ["exo-card"]\n        if eid in solved:\n            cls.append("ok")\n        if eid == etat["id"]:\n            cls.append("actif")\n        row.css_classes = cls\n        _stats_sb[eid].object = _STAT_PLEIN if eid in solved else _STAT_VIDE\n\n\n# --- Selection / verification ---------------------------------------------- #\ndef select(eid):\n    etat["id"] = eid\n    ex = exercice_par_id(eid)\n    exo_head.object = _exo_head_html(ex)\n    consigne.object = ex["consigne"]\n    editeur.value = ex["starter"]\n    titlebar.object = _titlebar_html(eid)\n    feedback.object = ""\n    bouton_sol.value = False\n    _maj_cartes()\n\n\ndef on_verifier(event):\n    eid = etat["id"]\n    ex = exercice_par_id(eid)\n    ok, md = verifier(ex, editeur.value)\n    feedback.object = md\n    if ok and eid not in solved:\n        solved.add(eid)\n        _maj_cartes()\n        maj_progress()\n\n\ndef on_reset(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["starter"]\n    feedback.object = ""\n    bouton_sol.value = False\n\n\ndef on_solution(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["solution"].strip() if bouton_sol.value else ex["starter"]\n\n\nbouton.on_click(on_verifier)\nbouton_reset.on_click(on_reset)\nbouton_sol.param.watch(on_solution, "value")\n\n\n# --- Assemblage de la sidebar ---------------------------------------------- #\nsidebar_items = [\n    pn.pane.HTML("<div class='sb-title'>Parcours d'exercices</div>"\n                 "<div class='sb-sub'>M\xe9tier d'analyste de fonds</div>"),\n]\n_base = [e for e in EXERCICES if e.get("niveau") != "avance"]\n_avance = [e for e in EXERCICES if e.get("niveau") == "avance"]\nif _base:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices de base \u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _base]\nif _avance:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices avanc\xe9s \u2605\u2605\u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _avance]\n\nsidebar = pn.Column(*sidebar_items, css_classes=["sidebar"],\n                    sizing_mode="stretch_width")\n\n# --- En-tete ---------------------------------------------------------------- #\nheader = pn.Row(\n    pn.pane.HTML(\n        "<div class='hdr-sub'>TgMaster University \xb7 B3 \u2014 AFE</div>"\n        "<div class='hdr-title'>Exercices Python \u2014 M\xe9tier d'analyste de fonds</div>"),\n    pn.HSpacer(),\n    progress,\n    css_classes=["app-header"], sizing_mode="stretch_width",\n)\n\n# --- Panneau principal ------------------------------------------------------ #\neditor_win = pn.Column(titlebar, editeur, css_classes=["editor-window"],\n                       sizing_mode="stretch_width")\nmain = pn.Column(\n    exo_head,\n    consigne,\n    editor_win,\n    pn.Row(bouton, bouton_reset, bouton_sol),\n    pn.pane.HTML("<div style='font-weight:700;color:#2b3576;margin-top:4px'>R\xe9sultat</div>"),\n    pn.Column(feedback, css_classes=["feedback-card"], sizing_mode="stretch_width"),\n    css_classes=["main-panel"], sizing_mode="stretch_width",\n)\n\nbody = pn.Row(sidebar, main, css_classes=["body-row"],\n              sizing_mode="stretch_width")\napp = pn.Column(header, body, sizing_mode="stretch_width", max_width=1240)\n\n# Etat initial\nmaj_progress()\nselect(etat["id"])\n\napp.servable(title="Exercices Python \u2014 AFE 14")\n\n\nawait write_doc()
  `

  try {
    const [docs_json, render_items, root_ids] = await self.pyodide.runPythonAsync(code)
    self.postMessage({
      type: 'render',
      docs_json: docs_json,
      render_items: render_items,
      root_ids: root_ids
    })
  } catch(e) {
    const traceback = `${e}`
    const tblines = traceback.split('\n')
    self.postMessage({
      type: 'status',
      msg: tblines[tblines.length-2]
    });
    throw e
  }
}

self.onmessage = async (event) => {
  const msg = event.data
  if (msg.type === 'rendered') {
    self.pyodide.runPythonAsync(`
    from panel.io.state import state
    from panel.io.pyodide import _link_docs_worker

    _link_docs_worker(state.curdoc, sendPatch, setter='js')
    `)
  } else if (msg.type === 'patch') {
    self.pyodide.globals.set('patch', msg.patch)
    self.pyodide.runPythonAsync(`
    from panel.io.pyodide import _convert_json_patch
    state.curdoc.apply_json_patch(_convert_json_patch(patch), setter='js')
    `)
    self.postMessage({type: 'idle'})
  } else if (msg.type === 'location') {
    self.pyodide.globals.set('location', msg.location)
    self.pyodide.runPythonAsync(`
    import json
    from panel.io.state import state
    from panel.util import edit_readonly
    if state.location:
        loc_data = json.loads(location)
        with edit_readonly(state.location):
            state.location.param.update({
                k: v for k, v in loc_data.items() if k in state.location.param
            })
    `)
  }
}

startApplication()